# SUCCESS
# STARTING PAPER FULL TEXT NOT IN DB
# SEMANTIC SCHOLAR NO REFERENCES RETURNED
# SEMANTIC SCHOLAR NO EMBEDDINGS
# LESS THAN 4 REFS IN UNARXIVE DATASET
# SEMANTIC SCHOLAR LESS THAN 4 SPECTER EMBEDDINGS
# LESS THAN 4 PAPERS SIMILAR ENOUGH
# ERROR DURING GENERATION OR GETTING ARXIV CATEGORIES OR JUDGEMENT

def getQuestionError(arxivId,db,allSquaiArxivIds):
    if arxivId in allPapersSuccessfull:
        return "SUCCESS"  
    starting_id = arxivId
    startingPaperFullText = getPaperFullText(db,starting_id)
    if startingPaperFullText is None:
        return "STARTING PAPER FULL TEXT NOT IN DB"
    paper_data = getPaperReferencesAndEmbeddingFromSemanticScholar(starting_id)
    if "references" not in paper_data:
        return "SEMANTIC SCHOLAR NO REFERENCES RETURNED"

    if not paper_data.get("embedding") or ("vector" not in paper_data["embedding"]): 
         return "SEMANTIC SCHOLAR NO EMBEDDINGS"
         
    startingPaperSpecterEmbedding = paper_data["embedding"]["vector"]

    # Filter references that exist in your SQuAI ID list
    valid_refs = [
        p for p in paper_data["references"]
        if p.get("externalIds") and p["externalIds"].get("ArXiv") in allSquaiArxivIds
    ]

    print(f"References: {len(paper_data['references'])}")
    print(f"References in squai dataset: {len(valid_refs)}")

    if len(valid_refs) < 4:
        return "LESS THAN 4 REFS IN UNARXIVE DATASET"

    paperCosineSimilarity = []

    for ref in valid_refs:
        paperId = ref["externalIds"]["ArXiv"]
        paperMeta = getPaperReferencesAndEmbeddingFromSemanticScholar(paperId)
       
        if not paperMeta.get("embedding") or ("vector" not in paperMeta["embedding"]): 
            continue
        embedding = paperMeta["embedding"]["vector"]
        # calculate cosine similarity with the original paper here
        cosineSimilarity = get_cosine_similarity(startingPaperSpecterEmbedding, embedding)
        
        paperCosineSimilarity.append({
            "paperId": paperId,
            "cosineSimilarity": cosineSimilarity
        })

    if len(paperCosineSimilarity) < 4:
        return "SEMANTIC SCHOLAR LESS THAN 4 SPECTER EMBEDDINGS"
    
    papersInThreshold = [ ref for ref in paperCosineSimilarity if 0.70 <= ref["cosineSimilarity"] <= 0.9]
    print(f"papers in threshold similarity: {len(papersInThreshold)}")
    

    final_papers = [{
        "ArXiv": starting_id,
        "text":  startingPaperFullText 
    }]
    while len(final_papers) < 5 and len(papersInThreshold ) > 0:
        potentialPaper = random.choice(papersInThreshold)
        arxivId = potentialPaper["paperId"]
        paperFullText = getPaperFullText(db,arxivId)
        if paperFullText is not None:
            final_papers.append({
            "ArXiv": arxivId,
            "text": paperFullText,
            "cosineSimilarity" : potentialPaper["cosineSimilarity"]
            })
        papersInThreshold.remove(potentialPaper)

    if len(final_papers) < 5: 
        return "LESS THAN 4 PAPERS SIMILAR ENOUGH"    
    return "ERROR DURING GENERATION OR GETTING ARXIV CATEGORIES OR JUDGEMENT"

def main():
    db = plyvel.DB(DB_PATH, create_if_missing=False)
    all_squai_ids = get_all_squai_arxiv_ids()

    allIdsTried = []
    with open('alreadyUsedArxivIds.txt', 'r', encoding='utf-8') as file:
        for line in file:
            # 'strip()' entfernt Leerzeichen und das Zeilenumbruch-Zeichen '\n' am Ende
            clean_line = line.strip()
            
            # Hier findet das Parsing statt
            if clean_line:
                allIdsTried.append(clean_line)
    print("------------------")
    print("alreadyUsedArxivIdsParsed:  " + str(len(allIdsTried)))
    print("------------------")

    progress = 0
    for arxivId in allIdsTried:
        questionError = None 
        category = None
        print("progress: " + str(progress))
        progress = progress + 1
        try:
            questionError = getQuestionError(arxivId, db, all_squai_ids)
            category = getCategoryFromArxiv(arxivId)
            with open(ERROR_OUTPUT_FILE, "a", encoding="utf-8") as f:
                f.write(json.dumps({
                    "arxiv": arxivId, "error": questionError, "category": category
                }) + "\n")
                print("error for " + arxivId + ": " + questionError)
            continue
        except: 
            with open(ERROR_OUTPUT_FILE, "a", encoding="utf-8") as f:
                f.write(json.dumps({"arxiv": arxivId, "error": questionError if questionError is not None else  "unknown", "category": category if category is not None else "unknown"}) + "\n")
            print("error for " + arxivId + "could not be determined")


        

main()